const TRN={alab:"كتاب الحياة",svd:"فاندايك",kjv:"KJV"};
function trAvail(){const b=book();if(b.trs)return ["alab",...b.trs];const t=window.TR&&window.TR[b.abbr];return t?Object.keys(TRN).filter(k=>k==="alab"||t[k]):[]}
